#ifndef FE2_SYSTEMS_SYSTEM_TABLES_H
#define FE2_SYSTEMS_SYSTEM_TABLES_H

/* Native systems tables (generated by tools/systems_tables_c.py). */
#include "system_record.h"
#include <stddef.h>

enum { FE2_PROFILES = 23 };

/* Profiles by size: the first threshold above the size selects the profile. */
extern const uint32_t *fe2_systems_profile_thresholds;
extern const uint32_t *fe2_systems_profile_or_object_references;
extern const uint16_t *fe2_systems_profile_kind;
extern const uint16_t *fe2_systems_profile_descriptor;
extern const uint16_t *fe2_systems_profile_temperature;
extern const uint16_t *fe2_systems_profile_subtree_position;
/* Saturating cumulative curve sampled every 0x40 positions. */
extern const uint16_t *fe2_systems_profile_curve;
/* Generated station models and (+0x1e, +0x12) field pairs. */
extern const uint16_t *fe2_systems_generated_descriptors;
extern const uint16_t *fe2_systems_station_orbit_parameters;
/* Sol records reused as station templates. */
extern fe2_system_record fe2_systems_sol_daedalus;
extern fe2_system_record fe2_systems_sol_abraham_lincoln;
extern fe2_system_record fe2_systems_sol_apollonius_city;
extern fe2_system_record fe2_systems_sol_galileo;

/* A handcrafted record list and its trailer (counters 0x202f..0x2032 and
 * station counts 0x204d/0x204e after loading). */
typedef struct fe2_system_template {
    const fe2_system_record *records;
    unsigned count;
    uint32_t counters;
    uint16_t stations;
} fe2_system_template;

typedef struct fe2_handcrafted_system {
    uint32_t key;
    const fe2_system_template *system;
} fe2_handcrafted_system;

extern fe2_handcrafted_system fe2_systems_handcrafted_systems[];
extern const unsigned fe2_systems_handcrafted_count;
extern const fe2_system_template *fe2_systems_fallback_system;
extern const fe2_system_template *fe2_systems_unloaded_system;

/* The static Frontier object: parent of every root record's object. */
extern const uint8_t *fe2_systems_static_object;
extern uint16_t fe2_systems_static_object_model;
extern uint8_t fe2_systems_static_object_handle;

int fe2_systems_bind(const uint8_t *image, size_t count);

#endif
